import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode.Argument;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode.Arithmetic;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode.BooleanAnd;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode.BooleanNot;
